roots=[R('-vert- / -vers-','Latin vertere','转；转向','回す；向ける','来自拉丁语 vertere（转）。转成别的形态 → convert；朝不同方向转 → diverse / divert；倒过来转 → invert / inverse。⚠️ controversy 里的 contro 是“相对”，不是 control。','ラテン語 vertere（回す）から。別の形に変える → convert；別々の方向へ → diverse / divert；ひっくり返す → invert / inverse。',[w['w'] for w in vert]),
R('-mit- / -miss-','Latin mittere','送；放','送る；放つ','来自拉丁语 mittere（送）。放行通过 → permit；全部交出 → commit；送出去 → emit / emission。⚠️ mit 与 miss 是同一词根的两种形式。','ラテン語 mittere（送る）から。通してやる → permit；すっかり差し出す → commit；外へ送る → emission。mit と miss は同じ語根の2つの形。',[w['w'] for w in mit]),
R('-pend- / -pens-','Latin pendere','悬挂；称重；支付','ぶら下がる；量る；支払う','来自拉丁语 pendere。“悬挂”义：depend（挂在别人身上）、pending（悬着）；“称重支付”义：expend、expense、compensate、pension。','ラテン語 pendere から。「ぶら下がる」：depend、pending。「量って支払う」：expend、expense、compensate、pension。',[w['w'] for w in pend]),
R('-press-','Latin premere','压','押す','来自拉丁语 premere（压）。向外压 → express；压在一起 → compress；压进心里 → impress；往回压 → repress。','ラテン語 premere（押す）から。外へ押し出す → express；押し縮める → compress；心に押す → impress；押し戻す → repress。',[w['w'] for w in press])]
